(()=>{'use strict';const $=id=>document.getElementById(id),p=new URLSearchParams(location.hash.slice(1)),room=p.get('room'),slot=Number(p.get('slot')),token=p.get('token');let peer=null,stream=null,cursor=0,polling=false,timer=null,waiting=[],stopped=true;const say=t=>$('phone-status').textContent=t;async function api(method,event){const r=await fetch('/api/studio/rooms/'+room+'/signals?slot='+slot+'&after='+cursor,{method,headers:{'content-type':'application/json','x-studio-token':token},...(event?{body:JSON.stringify({event})}:{})});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}async function poll(){if(stopped||polling)return;polling=true;try{const d=await api('GET');for(const e of d.events){if(e.payload.type==='answer'){await peer.setRemoteDescription({type:'answer',sdp:e.payload.sdp});for(const c of waiting)await peer.addIceCandidate(c);waiting=[];}else if(e.payload.type==='candidate'){if(peer.remoteDescription)await peer.addIceCandidate(e.payload.candidate);else waiting.push(e.payload.candidate);}else if(e.payload.type==='stop'){await stop();say('Studio stopped this camera. Ask for a fresh link.');}cursor=e.id;}}catch(e){say(e.message);if(/ended|invalid/i.test(e.message))await stop();}finally{polling=false;if(!stopped)timer=setTimeout(poll,1000);}}
async function stop(){stopped=true;clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop());peer?.close();peer=null;stream=null;$('phone-preview').srcObject=null;$('phone-start').disabled=false;$('phone-stop').disabled=true;}
$('phone-start').onclick=async()=>{if(!room||!token||!Number.isInteger(slot)||slot<1||slot>5){say('Open the camera link provided by your studio.');return;}if(!navigator.mediaDevices?.getUserMedia||!window.RTCPeerConnection){say('This browser does not support camera pairing. Try an up-to-date Chrome or Safari browser.');return;}$('phone-start').disabled=true;try{await stop();$('phone-start').disabled=true;stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:$('phone-facing').value},width:{ideal:1280},height:{ideal:720},frameRate:{ideal:24,max:30}},audio:$('phone-audio').checked?{echoCancellation:true}:false});$('phone-preview').srcObject=stream;peer=new RTCPeerConnection({iceServers:[]});stream.getTracks().forEach(t=>peer.addTrack(t,stream));let offerSent=false;const outbound=[];peer.onicecandidate=e=>{if(e.candidate){if(offerSent)api('POST',{type:'candidate',candidate:e.candidate.toJSON()}).catch(e=>say(e.message));else outbound.push(e.candidate.toJSON());}};peer.onconnectionstatechange=()=>say(peer?.connectionState==='connected'?'Connected — your studio is receiving this camera.':peer?.connectionState==='failed'?'Connection failed. Check that both devices share the same Wi-Fi.':'Camera connection: '+peer?.connectionState);const offer=await peer.createOffer();await peer.setLocalDescription(offer);await api('POST',{type:'offer',sdp:offer.sdp});offerSent=true;for(const candidate of outbound)await api('POST',{type:'candidate',candidate});stopped=false;$('phone-stop').disabled=false;say('Camera on. Waiting for the studio…');poll();}catch(e){await stop();say(e.name==='NotAllowedError'?'Camera permission was not granted. Allow access in your browser and retry.':e.message||'Camera unavailable.');}};
$('phone-stop').onclick=async()=>{await api('POST',{type:'stop'}).catch(()=>{});await stop();say('Camera disconnected.');};window.addEventListener('pagehide',()=>{stream?.getTracks().forEach(t=>t.stop());peer?.close();});if(slot)$('phone-title').textContent='Phone camera '+slot+'.';
})();
